import { MiddlewareContext } from "../context.js";
import { HTTP_NOT_FOUND, HTTP_SERVER_ERROR, serverLogger } from "../../../utils/index.js";
import { ensureError, getErrorMessage } from "../../../errors/index.js";
import { withSpan } from "../../../observability/tracing/otlp-setup.js";
function notFoundResponse() {
    return new Response("Not Found", { status: HTTP_NOT_FOUND });
}
export function executeMiddlewarePipeline(req, composedMiddleware, env, executionCtx, adapter, finalHandler) {
    return withSpan("middleware.pipeline.execute", async () => {
        const context = new MiddlewareContext(req, env ?? {}, executionCtx);
        try {
            const next = finalHandler
                ? () => Promise.resolve(finalHandler(req))
                : () => Promise.resolve(notFoundResponse());
            const response = await composedMiddleware(context, next);
            return response ?? notFoundResponse();
        }
        catch (error) {
            const normalizedError = ensureError(error);
            serverLogger.error("Middleware pipeline error:", {
                url: req.url,
                method: req.method,
                error: getErrorMessage(error),
                stack: normalizedError.stack,
            });
            const nodeEnv = adapter?.env.get("NODE_ENV") ?? "production";
            const body = {
                error: "Internal Server Error",
                method: req.method,
                url: req.url,
            };
            if (nodeEnv === "development") {
                body.message = normalizedError.message;
                body.stack = normalizedError.stack?.split("\n").slice(0, 10);
            }
            return new Response(JSON.stringify(body), {
                status: HTTP_SERVER_ERROR,
                headers: { "content-type": "application/json" },
            });
        }
    }, { "http.method": req.method, "http.url": req.url });
}
